def is_equal_to_sum_even(n):
    """Determines if the integer n can be expressed as the sum of four positive even integers.
    Returns True if n is even and at least 8, False otherwise."""
    if type(n) is not int:
        return False
    return n % 2 == 0 and n >= 8

